    "answer": "기본적 사실관계의 동일성은 자연적·사회적 사실과 피고인의 행위뿐 아니라 규범적 요소도 고려하여 판단한다.\n이 사안의 장물취득과 강도상해는 범행일시가 가깝고 목적물 일부가 같아도 일시·장소·수단·방법·상대방·행위태양·피해법익 등이 다르고 죄질에도 현저한 차이가 있어 동일성이 없다.\n따라서 장물취득 확정판결을 이유로 강도상해를 면소할 수 없고 그 처벌이 일사부재리에 반하지 않는다.",
