    "sourceQuote": "나. 공소사실이나 범죄사실의 동일성은 형사소송법상의 개념이므로 이것이 형사소송절차에서 가지는 의의나 소송법적 기능을 고려하 여야 할 것이고, 따라서 두 죄의 기본적 사실관계가 동일한가의 여 부는 그 규범적 요소를 전적으로 배제한 채 순수하게 사회적, 전법 률적인 관점에서만 파악할 수는 없고, 그 자연적, 사회적 사실관계 나 피고인의 행위가 동일한 것인가 외에 그 규범적 요소도 기본적 사실관계 동일성의 실질적 내용의 일부를 이루는 것이라고 보는 것이 상당하다.",
