    "answer": "도주차량죄의 운전자는 업무상과실 또는 중대한 과실로 사람을 사상에 이르게 한 자로서 무과실 사고 운전자는 포함되지 않는다.\n기소된 업무상과실이 인정되지 않으면 도로교통법상 사고후미조치 사실이 인정되어도 공소장변경 없이 그 죄로 처벌할 수 없다.\n공소사실에 대하여 범죄사실의 증명이 없으므로 무죄를 선고하여야 한다.",
