    "sourceQuote": "나. 형법 제268조의 죄를 범하고도 도로교통법 제50조 제1항의 규 정에 의한 조치를 취하지 아니하고 도주한 것이라는 공소사실로, 특정범죄가중처벌등에관한법률 제5조의3 제1항 제1호, 형법 제268 조 위반으로 기소되었으나 업무상과실이 인정되지 아니한 경우에 는 도로교통법 제50조 제1항 위반의 사실이 인정되는 경우라도 범 죄사실의 증명이 없는 경우로서 무죄를 선고하여야지, 공소장 변경 없이 도로교통법 제106조, 제50조 제1항을 적용하여 처벌할 수 없 다.",
