    "answer": "비소유자는 소유자의 권리행사방해에 가담한 경우 형법 제33조 본문에 따른 공범만 가능하고, 소유자에게 범죄가 성립하지 않으면 공동정범도 성립하지 않는다.\n이 사안은 피고인이 타인의 사무를 처리하는 자라고 쉽게 인정하기 어렵고, 권리행사방해와 배임은 구성요건·보호법익이 달라 직권 배임 인정이 방어권에 실질적 불이익을 줄 염려가 있다.\n배임을 인정하지 않는 것이 현저히 정의·형평에 반하지도 않으므로 직권 인정 의무가 없다.",
