    "answer": "상습범인 포괄일죄 일부의 확정판결은 사실심 선고 전 나머지 범행에 미쳐 면소하게 되지만, 선행판결에서 상습범으로 기소·처단되었어야 한다.\n선행사건이 비상습범인 기본 구성요건으로 처단되었다면 뒤에 드러난 사정으로 상습범 일부 판결로 바꾸어 볼 수 없다.\n따라서 뒤늦게 전체가 상습범 포괄일죄로 판단되어도 선고 전 나머지 범행에 그 기판력이 미치지 않는다.",
