    "sourceQuote": "다만 이러한 법리가 적용되기 위해서는 전의 확정판결에서 당해 피고인이 상습범으로 기소되어 처단되었을 것을 필요로 하는 것이고, 상습범 아닌 기본 구성요건의 범죄로 처단되는 데 그친 경우에는, 가사 뒤에 기소된 사건에서 비로소 드러났거나 새로 저 질러진 범죄사실과 전의 판결에서 이미 유죄로 확정된 범죄사실 등을 종합하여 비로소 그 모두가 상습범으로서의 포괄적 일죄에 해당하는 것으로 판단된다 하더라도 뒤늦게 앞서의 확정판결을 상 습범의 일부에 대한 확정판결이라고 보아 그 기판력이 그 사실심 판결 선고 전의 나머지 범죄에 미친다고 보아서는 아니 된다.",
