    "answer": "같은 장소·방법으로 시간적으로 접착하여 강취했어도 각 피해자에게 폭행·협박하여 각자 점유·관리하는 재물을 빼앗으면 피해자 수만큼 강도죄가 성립한다.\n반항 억압의 폭행·협박이 사실상 공통으로 이루어져 법률상 1개 행위라면 상상적 경합이다.\n다른 시기·장소에서 각 피해자를 폭행·협박한 경우에는 개별 강도 또는 강도상해의 실체적 경합이며 하나의 포괄적 강도상해로 묶지 않는다.",
