    "answer": "특수공무집행방해치상은 중한 결과를 예견할 수 있었으나 예견하지 못한 경우뿐 아니라 고의로 발생시킨 경우까지 포함하는 부진정결과적가중범이다.\n결과가 별도 고의범의 구성요건에 해당하고 그 고의범에 더 무거운 처벌규정이 있으면, 결과적가중범만 적용하여 가볍게 처벌할 수 없고 양 죄의 상상적 경합으로 처리한다.\n이 판결 당시에는 특수공무집행방해치상과 구 폭처법 제3조 제2항·제1항의 상해죄를 상상적 경합으로 처단한 원심을 유지하였다.",
