    "sourceQuote": "[2] 포괄일죄를 구성하는 일부 범죄사실이 먼저 단순일죄로 기소된 후 그 나머지 범죄사실이 포괄일죄로 추가기소되고 단순일죄의 범 죄사실도 추가 기소된 포괄일죄를 구성하는 행위의 일부임이 밝혀 진 경우라면, 그 추가기소에 의하여 전후에 기소된 각 범죄사실 전 부를 포괄일죄로 처벌할 것을 신청하는 취지가 포함되었다고 볼 수 있어, 공소사실을 추가하는 등의 공소장변경과는 절차상 차이가 있을 뿐 그 실질에 있어서 별 차이가 없으므로, 그 경우에 검사의 석명에 의하여 추가기소의 공소장 제출은 포괄일죄를 구성하는 행 위로서 먼저 기소된 공소장에 누락된 것을 추가 보충하고 죄명과 적용법조를 포괄일죄의 죄명과 적용법조로 변경하는 취지의 것으 로서 1개의 죄에 대하여 중복하여 공소를 제기한 것이 아님이 분 명하여진 경우에는, 그 추가기소에 의하여 공소장변경이 이루어진 것으로 보아 전후에 기소된 범죄사실 전부에 대하여 실체판단을 하여야 하고 추가기소에 대하여 공소기각판결을 할 필요가 없다.",
