    "sourceQuote": "형사소송법 제199조 제1항은 “수사에 관하여 그 목적을 달성하 기 위하여 필요한 조사를 할 수 있다. 다만, 강제처분은 이 법률에 특별한 규정이 있는 경우에 한하며, 필요한 최소한도의 범위 안에 서만 하여야 한다.”고 규정하여 임의수사의 원칙을 명시하고 있는 바, 수사관이 수사과정에서 당사자의 동의를 받는 형식으로 피의자 를 수사관서 등에 동행하는 것은, 상대방의 신체의 자유가 현실적 으로 제한되어 실질적으로 체포와 유사한 상태에 놓이게 됨에도, 영장에 의하지 아니하고 그 밖에 강제성을 띤 동행을 억제할 방법 도 없어서 제도적으로는 물론 현실적으로도 임의성이 보장되지 않 을 뿐만 아니라, 아직 정식의 체포ㆍ구속단계 이전이라는 이유로 상대방에게 헌법 및 형사소송법이 체포ㆍ구속된 피의자에게 부여 하는 각종의 권리보장 장치가 제공되지 않는 등 형사소송법의 원 리에 반하는 결과를 초래할 가능성이 크므로, 수사관이 동행에 앞 서 피의자에게 동행을 거부할 수 있음을 알려 주었거나 동행한 피 의자가 언제든지 자유로이 동행과정에서 이탈 또는 동행장소로부 터 퇴거할 수 있었음이 인정되는 등 오로지 피의자의 자발적인 의 사에 의하여 수사관서 등에의 동행이 이루어졌음이 객관적인 사정 에 의하여 명백하게 입증된 경우에 한하여, 그 적법성이 인정되는 것으로 봄이 상당하다. 형사소송법 제200조 제1항에 의하여 검사 또는 사법경찰관이 피의자에 대하여 임의적 출석을 요구할 수는 있겠으나, 그 경우에도 수사관이 단순히 출석을 요구함에 그치지 않고 일정 장소로의 동행을 요구하여 실행한다면 위에서 본 법리 가 적용되어야 할 것이고, 한편 행정경찰 목적의 경찰활동으로 행 하여지는 경찰관직무집행법 제3조 제2항 소정의 질문을 위한 동행 요구도 형사소송법의 규율을 받는 수사로 이어지는 경우에는 역시 위에서 본 법리가 적용되어야 할 것이다.",
