    "answer": "현행범체포에는 가벌성·현행성 및 시간적 접착성·범인과 범죄의 명백성 외에 도망 또는 증거인멸 우려라는 체포의 필요성이 있어야 한다.\n체포 당시 상황을 기준으로 판단하며 경험칙상 현저히 합리성을 잃은 체포는 위법하다.\n신원 확인이 되었고 목격자도 있는 경미·우발적 모욕의 이 사건에서는 필요성이 없어 공무집행방해가 성립하지 않고 저항 중 상해는 정당방위이다.",
