    "sourceQuote": "현행범인은 누구든지 영장 없이 체포할 수 있다(형사소송법 제 212조). 현행범인으로 체포하기 위하여는 행위의 가벌성, 범죄의 현행성·시간적 접착성, 범인·범죄의 명백성 이외에 체포의 필요성 즉, 도망 또는 증거인멸의 염려가 있어야 하고, 이러한 요건을 갖 추지 못한 현행범인 체포는 법적 근거에 의하지 아니한 영장 없는 체포로서 위법한 체포에 해당한다 (대법원 1999. 1. 26. 선고 98도 3029 판결 등 참조). 여기서 현행범인 체포의 요건을 갖추었는지는 체포 당시 상황을 기초로 판단하여야 하고, 이에 관한 검사나 사법 경찰관 등 수사주체의 판단에는 상당한 재량의 여지가 있다고 할 것이나, 체포 당시의 상황으로 보아서도 그 요건의 충족 여부에 관 한 검사나 사법경찰관 등의 판단이 경험칙에 비추어 현저히 합리 성을 잃은 경우에는 그 체포는 위법하다고 보아야 한다.",
