    "sourceQuote": " 사법경찰리가 현행범인으로 체포하는 경우에는 반드시 범죄사 실의 요지, 구속의 이유와 변호인을 선임할 수 있음을 말하고 변명할 기회를 주어야 할 것임은 명백하며, 이러한 법리는 비 단 현행범인을 체포하는 경우뿐만 아니라 긴급체포의 경우에 도 마찬가지로 적용되는 것이고, 이와 같은 고지는 체포를 위 한 실력행사에 들어가기 이전에 미리 하여야 하는 것이 원칙 이나, 달아나는 피의자를 쫓아가 붙들거나 폭력으로 대항하는 피의자를 실력으로 제압하는 경우에는 붙들거나 제압하는 과 정에서 하거나, 그것이 여의치 않은 경우에라도 일단 붙들거나 제압한 후에는 지체 없이 행하여야 함(→ 적법한 공무집행 아 님. 원심의 정당방위 판단 유지, 단 폭행 범의 부정은 달리 판 단함 → 결론에 영향을 미치지 않아 상고기각)",
