    "answer": "사인이 체포한 현행범은 즉시 검사·사법경찰관리에게 인도해야 한다.\n'즉시'는 반드시 체포 순간과 밀착된 시점이 아니라 정당한 이유 없는 지연·불필요한 지체가 없다는 뜻이다.\n불필요한 지체 없이 인도했다면 48시간은 사인의 체포시가 아니라 수사기관이 인도받은 때부터 기산한다. 그 안에 구속영장을 청구하지 않으면 즉시 석방한다.",
