    "sourceQuote": "현행범인은 누구든지 영장 없이 체포할 수 있고(형사소송법 제 212조), 검사 또는 사법경찰관리(이하 ‘검사 등’이라고 한다) 아닌 이가 현행범인을 체포한 때에는 즉시 검사 등에게 인도하여야 한 다( 형사소송법 제213조 제1항). 여기서 ‘즉시’라고 함은 반드시 체 포시점과 시간적으로 밀착된 시점이어야 하는 것은 아니고, ‘정당한 이유 없이 인도를 지연하거나 체포를 계속하는 등으로 불필요한 지체를 함이 없이’라는 뜻으로 볼 것이다. 또한 검사 등이 현행범 인을 체포하거나 현행범인을 인도받은 후 현행범인을 구속하고자 하는 경우 48시간 이내에 구속영장을 청구하여야 하고 그 기간 내 에 구속영장을 청구하지 아니하는 때에는 즉시 석방하여야 한다 (형사소송법 제213조의2, 제200조의2 제5항). 위와 같이 체포된 현 행범인에 대하여 일정 시간 내에 구속영장 청구 여부를 결정하도 록 하고 그 기간 내에 구속영장을 청구하지 아니하는 때에는 즉시 석방하도록 한 것은 영장에 의하지 아니한 체포 상태가 부당하게 장기화되어서는 안 된다는 인권보호의 요청과 함께 수사기관에서 구속영장 청구 여부를 결정하기 위한 합리적이고 충분한 시간을 보장해 주려는 데에도 그 입법취지가 있다고 할 것이다. 따라서 검 사 등이 아닌 이에 의하여 현행범인이 체포된 후 불필요한 지체 없이 검사 등에게 인도된 경우 위 48시간의 기산점은 체포시가 아 니라 검사 등이 현행범인을 인도받은 때라고 할 것이다.",
