    "sourceQuote": " 헌법이 정한 적법절차와 영장주의 원칙, 형사소송법이 정한 체 포된 피의자의 구금을 위한 구속영장의 청구, 발부, 집행절차 에 관한 규정을 종합하면, 법관이 검사의 청구에 의하여 체포 된 피의자의 구금을 위한 구속영장을 발부하면 검사와 사법경 찰관리는 지체 없이 신속하게 구속영장을 집행하여야 한다.  피의자에 대한 구속영장의 제시와 집행이 그 발부 시로부터 정당한 사유 없이 시간이 지체되어 이루어졌다면, 구속영장이 그 유효기간 내에 집행되었다고 하더라도 위 기간 동안의 체 포 내지 구금 상태는 위법하다.  사법경찰리가 현행범인 체포된 피의자에 대하여 구속영장 발 부일로부터 만 3일이 경과하여 구속영장 원본 제시에 의한 구 속영장을 집행한 사안에서, 사법경찰리의 피고인에 대한 구속 영장 집행은 지체 없이 이루어졌다고 볼 수 없고, 구속영장이 주말인 토요일에 발부되어 담당경찰서의 송치담당자가 월요일 일과시간 중 이를 받아왔고 피고인에 대한 사건 담당자가 외 근 수사 중이어서 화요일에 구속영장 원본 제시에 의한 집행 을 한 사정은 구속영장 집행 지연에 대한 정당한 사유에 해당 하지 않는다고 보아 구속영장의 집행이 정당한 사유 없이 지 체된 기간 동안의 피고인에 대한 체포 내지 구금 상태는 위법 하다고 판단하였음.  다만, 피고인에 대한 구속영장 집행이 위법하더라도 그로 인하 여 피고인의 방어권, 변호권이 본질적으로 침해되어 원심판결 의 정당성마저 인정하기 어렵다고 보이는 정도에 이르지 않았 다고 보아 피고인의 상고를 기각하였음.",
