    "sourceQuote": "구속의 효력은 원칙적으로 위 방식에 따라 작성된 구속영장에 기재된 범죄사실에만 미치는 것이므로, 구속기간이 만료될 무렵에 종전 구속영장에 기재된 범죄사실과 다른 범죄사실로 피고인을 구속하였다는 사정만으로는 피고인에 대한 구속이 위법하다고 할 수 없다. 형사소송법 제72조는 구속영장을 집행함에 있어 집 행기관이 취하여야 하는 절차가 아니라 구속영장 발 부함에 있어 수소법원 등 법관이 취하여야 하는 절 차라 할 것이므로, 법원이 피고인에 대하여 구속영장 을 발부함에 있어 사전에 위 규정에 따른 절차를 거 치지 아니한 채 구속영장을 발부하였다면 그 발부결 정은 위법하다고 할 것이나, 위 규정은 피고인의 절 차적 권리를 보장하기 위한 규정이므로 이미 변호인 을 선정하여 공판절차에서 변명과 증거의 제출을 다 하고 그의 변호 아래 판결을 선고받은 경우 등과 같 이 위 규정에서 정한 절차적 권리가 실질적으로 보 장되었다고 볼 수 있는 경우에는, 이에 해당하는 절 차의 전부 또는 일부를 거치지 아니한 채 구속영장 을 발부하였다 하더라도 이러한 점만으로 그 발부결 정이 위법하다고 볼 것은 아니다",
