    "sourceQuote": "검사 또는 사법경찰관은 범죄수사에 필요한 때에는 피의자가 죄 를 범하였다고 의심할 만한 정황이 있는 경우에 판사로부터 발부 받은 영장에 의하여 압수·수색을 할 수 있으나, 압수·수색은 영장 발부의 사유로 된 범죄 혐의사실과 관련된 증거에 한하여 할 수 있으므로, 영장 발부의 사유로 된 범죄 혐의사실과 무관한 별개의 증거를 압수하였을 경우 이는 원칙적으로 유죄 인정의 증거로 사 용할 수 없다. 다만 수사기관이 별개의 증거를 피압수자 등에게 환부하고 후에 임의제출받아 다시 압수하였다면 증거를 압수한 최초의 절차 위반 행위와 최종적인 증거수집 사이의 인과관계가 단절되었다고 평가 할 수 있으나, 환부 후 다시 제출하는 과정에서 수사기관의 우월적 지위에 의하여 임의제출 명목으로 실질적으로 강제적인 압수가 행 하여질 수 있으므로, 제출에 임의성이 있다는 점에 관하여는 검사 가 합리적 의심을 배제할 수 있을 정도로 증명하여야 하고, 임의로 제출된 것이라고 볼 수 없는 경우에는 증거능력을 인정할 수 없다. [이 사건의 경우] 환부 후 실질적 임의제출이 있었다고 볼 수도 없어 최초의 절차 위반행위와 최종적 증거수집 사이의 인과관계가 단절되지 않았다 고 봄(검사의 증명 실패)",
