    "caution": "단순히 동종 또는 유사한 범행이라는 사정만으로 객관적 관련성이 인정되지 않는다.",
    "sourceQuote": "형사소송법 제215조 제1항은 “검사는 범죄수사에 필요한 때에는 피의자가 죄를 범하였다고 의심할 만한 정황이 있고 해당 사건과 관계가 있다고 인정할 수 있는 것에 한정하여 지방법원판사에게 청구하여 발부받은 영장에 의하여 압수∙수색 또는 검증을 할 수 있다.”라고 정하고 있다. 따라서 영장 발부의 사유로 된 범죄 혐의 사실과 무관한 별개의 증거를 압수하였을 경우 이는 원칙적으로 유죄 인정의 증거로 사용할 수 없다. 그러나 압수·수색의 목적이 된 범죄나 이와 관련된 범죄의 경우에는 그 압수·수색의 결과를 유 죄의 증거로 사용할 수 있다. 압수·수색영장의 범죄 혐의사실과 관계있는 범죄라는 것은 압수· 수색영장에 기재한 혐의사실과 객관적 관련성이 있고 압수·수색영 장 대상자와 피의자 사이에 인적 관련성이 있는 범죄를 의미한다. 그중 혐의사실과의 객관적 관련성은 압수·수색영장에 기재된 혐의 사실 자체 또는 그와 기본적 사실관계가 동일한 범행과 직접 관련 되어 있는 경우는 물론 범행 동기와 경위, 범행 수단과 방법, 범행 시간과 장소 등을 증명하기 위한 간접증거나 정황증거 등으로 사 용될 수 있는 경우에도 인정될 수 있다. 그 관련성은 압수·수색영장에 기재된 혐의사실의 내용과 수사의 대상, 수사 경위 등을 종합하여 구체적·개별적 연관관계가 있는 경 우에만 인정되고, 혐의사실과 단순히 동종 또는 유사 범행이라는 사유만으로 관련성이 있다고 할 것은 아니다. 그리고 피의자와 사이의 인적 관련성은 압수·수색영장에 기재된 대상자의 공동정범이나 교사범 등 공범이나 간접정범은 물론 필요 적 공범 등에 대한 피고사건에 대해서도 인정될 수 있다.",
