    "sourceQuote": "경우라면, 더 이상의 추가 탐색을 중단하고 법원으로부터 이 사건 전자정보에 대한 압수·수색영장을 발부받아야 함에도 수사기관은 별도의 압수·수색영장을 발부받지 아니하였다. 따라서 이 사건 전자정보 출력물은 형사소송법 제308조의2에서 정한 위법수집증거에 해당하여 유죄의 증거로 쓸 수 없고, 그와 같 은 절차적 위법은 헌법에 규정된 영장주의 내지 적법절차의 실질 적 내용을 침해하는 경우에 해당하므로, 예외적으로 증거능력을 인 정할 수도 없다. [대법원 판단] ✓ 수사기관은 범죄수사의 필요성이 있고 피의자가 죄를 범하였 다고 의심할 만한 정황이 있는 경우에도 해당 사건과 관계가 있다고 인정할 수 있는 것에 한하여 영장을 발부받아 압수·수 색을 할 수 있다. 영장 발부의 사유로 된 범죄 혐의사실과 관 련된 증거가 아니라면 적법한 압수·수색이 아니다. 따라서 영 장 발부의 사유로 된 범죄 혐의사실과 무관한 별개의 증거를 압수하였을 경우 이는 원칙적으로 유죄 인정의 증거로 사용할 수 없다. → 원심 판단 정당함 ✓ 피고인의 검찰 진술과 법정진술의 증거능력에 대한 원심 판단 정당 (원심) 위법수집증거의 2차적 증거로서 인과관계가 희석 또는 단 절되지 아니하였다는 이유로 증거능력을 인정하지 아니함: ( 가) 피 고인의 진술은 위법수집증거인 이 사건 전자정보 출력물을 직접 제시받고 한 것과 같거나, 적어도 피고인의 진술은 이 사건 전자정 보 출력물의 내용을 전제로 한 신문에 답변한 것으로 볼 수 있다. (나) 피고인이 당시 이 사건 전자정보 출력물이 위법수집증거에 해 당할 수 있다는 점을 고지받거나 그러한 내용의 법적 조언을 받지 못했다.",
