    "caution": "기술적으로 접속할 수 있다는 사정과 영장으로 허용된 범위는 다르다.",
    "sourceQuote": "헌법과 형사소송법이 구현하고자 하는 적법절차와 영장주의의 정신에 비추어 볼 때, 법관이 압수·수색영장을 발부하면서 ‘압수할 물건’을 특정하기 위하여 기재한 문언은 엄격하게 해석해야 하고, 함부로 피압수자 등에게 불리한 내용으로 확장해석 또는 유추해석 을 하는 것은 허용될 수 없다(대법원 2009. 3. 12. 선고 2008도 763 판결 참조). 압수할 전자정보가 저장된 저장매체로서 압수·수색영장에 기재된 수색장소에 있는 컴퓨터, 하드디스크, 휴대전화와 같은 컴퓨터 등 정보처리장치와 수색장소에 있지는 않으나 컴퓨터 등 정보처리장 치와 정보통신망으로 연결된 원격지의 서버 등 저장매체(이하 ‘원 격지 서버’라 한다)는 소재지, 관리자, 저장 공간의 용량 측면에서 서로 구별된다. 원격지 서버에 저장된 전자정보를 압수·수색하기 위해서는 컴퓨터 등 정보처리장치를 이용하여 정보통신망을 통해 원격지 서버에 접속하고 그곳에 저장되어 있는 전자정보를 컴퓨터 등 정보처리장치로 내려 받거나 화면에 현출시키는 절차가 필요하 므로, 컴퓨터 등 정보처리장치 자체에 저장된 전자정보와 비교하여 압수·수색의 방식에 차이가 있다. 원격지 서버에 저장되어 있는 전 자정보와 컴퓨터 등 정보처리장치에 저장되어 있는 전자정보는 그 내용이나 질이 다르므로 압수·수색으로 얻을 수 있는 전자정보의 범위와 그로 인한 기본권 침해 정도도 다르다. 따라서 수사기관이 압수·수색영장에 적힌 ‘수색할 장소’에 있는 컴퓨터 등 정보처리장치에 저장된 전자정보 외에 원격지 서버에 저장된 전자정보를 압수·수색하기 위해서는 압수·수색영장에 적힌 ‘압수할 물건’에 별도로 원격지 서버 저장 전자정보가 특정되어 있 어야 한다. 압수·수색영장에 적힌 ‘압수할 물건’에 컴퓨터 등 정보 처리장치 저장 전자정보만 기재되어 있다면 컴퓨터 등 정보처리장 치를 이용하여 원격지 서버 저장 전자정보를 압수할 수는 없다.",
