    "sourceQuote": "음주운전 중 교통사고를 야기한 후 피의자가 의식불명 상태에 빠져 있는 등으로 도로교통법이 음주운전의 제1차적 수사방법으로 규정한 호흡조사에 의한 음주측정이 불가능하고 혈액 채취에 대한 동의를 받을 수도 없을 뿐만 아니라 법원으로부터 혈액 채취에 대 한 감정처분허가장이나 사전 압수영장을 발부받을 시간적 여유도 없는 긴급한 상황이 생길 수 있다. 이러한 경우 피의자의 신체 내지 의복류에 주취로 인한 냄새가 강 하게 나는 등 형사소송법 제211조 제2항 제3호가 정하는 범죄의 증적이 현저한 준현행범인의 요건이 갖추어져 있고 교통사고 발생 시각으로부터 사회통념상 범행 직후라고 볼 수 있는 시간 내라면, 피의자의 생명·신체를 구조하기 위하여 사고현장으로부터 곧바로 후송된 병원 응급실 등의 장소는 형사소송법 제216조 제3항의 범 죄 장소에 준한다 할 것이므로, 검사 또는 사법경찰관은 피의자의 혈중알코올농도 등 증거의 수집을 위하여 의료법상 의료인의 자격 이 있는 자로 하여금 의료용 기구로 의학적인 방법에 따라 필요최 소한의 한도 내에서 피의자의 혈액을 채취하게 한 후 그 혈액을 영장 없이 압수할 수 있다. 다만 이 경우에도 형사소송법 제216조 제3항 단서, 형사소송규 칙 제58조, 제107조 제1항 제3호에 따라 사후에 지체 없이 강제채 혈에 의한 압수의 사유 등을 기재한 영장청구서에 의하여 법원으 로부터 압수영장을 받아야 한다.",
