    "answer": "강제채뇨는 혐의·범죄 중대성, 분석의 유용성·필요성 및 대체수단의 곤란성 등을 보아 부득이한 경우 최후수단으로 적법절차에 따라 허용된다.\n적합한 장비·시설에서 숙련된 의료인 등이 신체·건강 위험과 굴욕감을 최소화해야 한다.\n적법한 압수수색영장으로 채뇨할 때 확보 노력에도 임의 이동을 기대할 수 없다면 적합한 장소로 데려가기 위한 필요최소한 유형력은 영장 집행에 필요한 처분으로 허용된다.",
