    "caution": "소변영장이 있다는 이유만으로 장소·방식에 제한 없는 강제채뇨나 이동이 허용되는 것은 아니다.",
    "sourceQuote": "강제 채뇨는 피의자가 임의로 소변을 제출하지 않는 경우 피의 자에 대하여 강제력을 사용해서 도뇨관(catheter)을 요도를 통하여 방광에 삽입한 뒤 체내에 있는 소변을 배출시켜 소변을 취득·보관 하는 행위이다. 수사기관이 범죄 증거를 수집할 목적으로 하는 강 제 채뇨는 피의자의 신체에 직접적인 작용을 수반할 뿐만 아니라 피의자에게 신체적 고통이나 장애를 초래하거나 수치심이나 굴욕 감을 줄 수 있다. 따라서 피의자에게 범죄 혐의가 있고 그 범죄가 중대한지, 소변성분 분석을 통해서 범죄 혐의를 밝힐 수 있는지, 범죄 증거를 수집하기 위하여 피의자의 신체에서 소변을 확보하는 것이 필요한 것인지, 채뇨가 아닌 다른 수단으로는 증명이 곤란한 지 등을 고려하여 범죄 수사를 위해서 강제 채뇨가 부득이하다고 인정되는 경우에 최후의 수단으로 적법한 절차에 따라 허용된다고 보아야 한다. 이때 의사, 간호사, 그 밖의 숙련된 의료인 등으로 하 여금 소변 채취에 적합한 의료장비와 시설을 갖춘 곳에서 피의자 의 신체와 건강을 해칠 위험이 적고 피의자의 굴욕감 등을 최소화 하는 방법으로 소변을 채취하여야 한다. 수사기관이 범죄 증거를 수집할 목적으로 피의자의 동의 없이 피의자의 소변을 채취하는 것은 법원으로부터 감정허가장을 받아 형사소송법 제221조의4 제1항, 제173조 제1항에서 정한 ‘감정에 필요한 처분’으로 할 수 있지만(피의자를 병원 등에 유치할 필요가 있는 경우에는 형사소송법 제221조의3에 따라 법원으로부터 감정 유치장을 받아야 한다), 형사소송법 제219조, 제106조 제1항, 제 109조에 따른 압수·수색의 방법으로도 할 수 있다. 이러한 압수·수 색의 경우에도 수사기관은 원칙적으로 형사소송법 제215조에 따라 판사로부터 압수·수색영장을 적법하게 발부받아 집행해야 한다.",
