    "sourceQuote": "피의자가 동행을 거부하는 의사를 표시하였음에도 불구하고 경 찰관들이 영장에 의하지 아니하고 피의자를 강제로 연행한 행위는 수사상의 강제처분에 관한 형사소송법상의 절차를 무시한 채 이루 어진 것으로 피고인을 강제로 연행한 조치는 위법한 조치에 해당 하고, 위법한 체포상태에서 이루어진 채뇨 요구 또한 위법하므로 그에 의하여 수집된 '소변검사시인서'는 유죄 인정의 증거로 삼을 수 없으나(1차 채뇨), 한편 연행 당시 피고인이 마약을 투약한 것이거나 자살할지도 모른다는 취지의 구체적 제보가 있었던 데다가, 피고인이 경찰관 앞에서 바지와 팬티를 내리는 등 비상식적인 행동을 하였던 사정 등에 비추어 피고인에 대한 긴급한 구호의 필요성이 전혀 없었다 고 볼 수 없는 점, 경찰관들은 임의동행시점으로부터 얼마 지나지 아니하여 체포의 이유와 변호인 선임권 등을 고지하면서 피고인에 대한 긴급체포의 절차를 밟는 등 절차의 잘못을 시정하려고 한 바 있어, 경찰관들의 위와 같은 임의동행조치는 단지 수사의 순서를 잘못 선택한 것이라고 할 수 있지만 관련 법규정으로부터의 실질 적 일탈 정도가 헌법에 규정된 영장주의 원칙을 현저히 침해할 정 도에 이르렀다고 보기 어려운 점 등에 비추어 볼 때, 위와 같은 2 차적 증거 수집이 위법한 체포·구금절차에 의하여 형성된 상태를 직접 이용하여 행하여진 것으로는 쉽사리 평가할 수 없으므로, 이 압수 ∙ 수색 ∙ 검증 - 5 7 - 6 주차 영 장 실 무 와 같은 사정은 체포과정에서의 절차적 위법과 2차적 증거 수집 사이의 인과관계를 희석하게 할 만한 정황에 속하고, 메스암페타민 투약 범행의 중대성도 아울러 참작될 필요가 있는 점 등 제반 사 정을 고려할 때 2차적 증거인 소변 감정서 등은 증거능력이 인정 된다.",
