    "answer": "원칙은 혐의 관련 부분만 현장에서 출력하거나 휴대한 매체에 파일 복사하는 것이다.\n현장 선별이 불가능하거나 현저히 곤란한 부득이한 사정이 있고 영장에 반출 방식이 기재되며 실제 그 사정이 생긴 때에만 예외적으로 원본·복제본 반출이 허용된다.\n반출 후 탐색·출력도 영장집행의 일부로서 관련 부분에 한정해야 하고, 전체 과정의 참여권과 전자정보 목록 작성·교부 등 왜곡·오남용 방지조치를 갖춰야 한다.",
