    "caution": "저장매체 반출이 허용된 것과 저장정보 전부의 무차별 복제·출력이 허용된 것은 다르다.",
    "sourceQuote": "전자정보에 대한 압수·수색영장의 집행에 있어서는 원칙적으로 영장 발부의 사유로 된 혐의사실과 관련된 부분만을 문서 출력물 로 수집하거나 수사기관이 휴대한 저장매체에 해당 파일을 복사하 는 방식으로 이루어져야 하고, 집행현장의 사정상 위와 같은 방식 에 의한 집행이 불가능하거나 현저히 곤란한 부득이한 사정이 존 재하더라도 그와 같은 경우에 그 저장매체 자체를 직접 혹은 하드 카피나 이미징 등 형태로 수사기관 사무실 등 외부로 반출하여 해 당 파일을 압수·수색할 수 있도록 영장에 기재되어 있고 실제 그와 같은 사정이 발생한 때에 한하여 예외적으로 허용될 수 있을 뿐이 다. 나아가 이처럼 저장매체 자체를 수사기관 사무실 등으로 옮긴 후 영장에 기재된 범죄 혐의 관련 전자정보를 탐색하여 해당 전자 정보를 문서로 출력하거나 파일을 복사하는 과정 역시 전체적으로 압수·수색영장 집행의 일환에 포함된다고 보아야 한다. 따라서 그러한 경우의 문서출력 또는 파일복사의 대상 역시 혐 의사실과 관련된 부분으로 한정되어야 함은 헌법 제12조 제1항, 제3항, 형사소송법 제114조, 제215조의 적법절차 및 영장주의의 원칙상 당연하다. 그러므로 수사기관 사무실 등으로 옮긴 저장매체 에서 범죄 혐의와의 관련성에 대한 구분 없이 저장된 전자정보 중 임의로 문서출력 혹은 파일복사를 하는 행위는 특별한 사정이 없 는 한 영장주의 등 원칙에 반하는 위법한 집행이 된다.",
