    "sourceQuote": "저장매체에 대한 압수·수색 과정에서 범위를 정하여 출력 또는 복제하는 방법이 불가능하거나 압수의 목 적을 달성하기에 현저히 곤란한 예외적인 사정이 인 정되어 전자정보가 담긴 저장매체 또는 하드카피나 이미징 등 형태(이하 ‘복제본’이라 한다)를 수사기관 사무실 등으로 옮겨 복제·탐색·출력하는 경우에도, 그와 같은 일련의 과정에서 형사소송법 제219조, 제 121조에서 규정하는 피압수·수색 당사자(이하 ‘피압 수자’라 한다)나 변호인에게 참여의 기회를 보장하고 혐의사실과 무관한 전자정보의 임의적인 복제 등을 막기 위한 적절한 조치를 취하는 등 영장주의 원칙 과 적법절차를 준수하여야 한다 준항고인이 전체 압수·수색 과정을 단계적·개별적으 로 구분하여 각 단계의 개별 처분의 취소를 구하더 라도 준항고법원은 특별한 사정이 없는 한 구분된 개별 처분의 위법이나 취소 여부를 판단할 것이 아 니라 당해 압수·수색 과정 전체를 하나의 절차로 파 악하여 그 과정에서 나타난 위법이 압수·수색 절차 전체를 위법하게 할 정도로 중대한지 여부에 따라 전체적으로 압수·수색 처분을 취소할 것인지를 가려 야 한다 전자정보에 대한 압수·수색이 종료되기 전에 혐의사 실과 관련된 전자정보를 적법하게 탐색하는 과정에 서 별도의 범죄혐의와 관련된 전자정보를 우연히 발 견한 경우라면, 수사기관은 더 이상의 추가 탐색을 중단하고 법원에서 별도의 범죄혐의에 대한 압수·수 색영장을 발부받은 경우에 한하여 그러한 정보에 대 하여도 적법하게 압수·수색을 할 수 있다",
