    "sourceQuote": "압수물인 컴퓨터용 디스크 그 밖에 이와 비슷한 정보저장매체 (이하 ‘정보저장매체’라고만 한다)에 입력하여 기억된 문자정보 또 는 그 출력물(이하 ‘출력 문건’이라 한다)을 증거로 사용하기 위해 서는 정보저장매체 원본에 저장된 내용과 출력 문건의 동일성이 인정되어야 하고, 이를 위해서는 정보저장매체 원본이 압수 시부터 문건 출력 시까지 변경되지 않았다는 사정, 즉 무결성이 담보되어 야 한다. 특히 정보저장매체 원본을 대신하여 저장매체에 저장된 자료를 ‘하드카피’ 또는 ‘이미징’한 매체로부터 출력한 문건의 경우에는 정 보저장매체 원본과 ‘하드카피’ 또는 ‘이미징’한 매체 사이에 자료의 동일성도 인정되어야 할 뿐만 아니라, 이를 확인하는 과정에서 이 용한 컴퓨터의 기계적 정확성, 프로그램의 신뢰성, 입력·처리·출력 의 각 단계에서 조작자의 전문적인 기술능력과 정확성이 담보되어 야 한다. 이 경우 출력 문건과 정보저장매체에 저장된 자료가 동일하고 정보저장매체 원본이 문건 출력 시까지 변경되지 않았다는 점은, 피압수·수색 당사자가 정보저장매체 원본과 ‘하드카피’ 또는 ‘이미 징’한 매체의 해쉬(Hash) 값이 동일하다는 취지로 서명한 확인서면 을 교부받아 법원에 제출하는 방법에 의하여 증명하는 것이 원칙 이나, 그와 같은 방법에 의한 증명이 불가능하거나 현저히 곤란한 경 우에는, 정보저장매체 원본에 대한 압수, 봉인, 봉인해제, ‘하드카피’ 또는 ‘이미징’ 등 일련의 절차에 참여한 수사관이나 전문가 등의 증언에 의해 정보저장매체 원본과 ‘하드카피’ 또는 ‘이미징’한 매체 사이의 해쉬 값이 동일하다거나 정보저장매체 원본이 최초 압수 시부터 밀봉되어 증거 제출 시까지 전혀 변경되지 않았다는 등의 전자정보 압수 ∙ 수색 - 6 8 - 6 주차 영 장 실 무 사정을 증명하는 방법 또는 법원이 그 원본에 저장된 자료와 증거 로 제출된 출력 문건을 대조하는 방법 등으로도 그와 같은 무결성· 동일성을 인정할 수 있으며, 반드시 압수·수색 과정을 촬영한 영상 녹화물 재생 등의 방법으로만 증명하여야 한다고 볼 것은 아니다.",
