    "answer": "저장매체 반출 후 탐색·복제·출력의 일련 과정에도 참여기회 보장과 파일 명세가 특정된 압수목록 작성·교부 등이 필요하다.\n명시적 불참 의사 또는 참여권의 실질적 침해가 없다는 특별한 사정이 없다면 관련 정보만 뽑았어도 위법하다.\n그렇게 얻은 증거는 위법수집증거이며 사후영장 발부나 피고인·변호인의 증거동의로 치유되지 않는다.",
