    "caution": "원래 휴대전화 압수영장이 있었다는 것과 이후 전자정보 탐색·복제·출력 과정이 적법하다는 것은 별개이다.",
    "sourceQuote": "압수의 대상이 되는 전자정보와 그렇지 않은 전자정보가 혼재된 정보저장매체나 그 복제본을 압수ㆍ수색한 수사기관이 정보저장매 체 등을 수사기관 사무실 등으로 옮겨 이를 탐색ㆍ복제ㆍ출력하는 경우, 그와 같은 일련의 과정에서 형사소송법 제219조, 제121조에 서 규정하는 피압수ㆍ수색 당사자(이하 ‘피압수자’라 한다)나 변호 인에게 참여의 기회를 보장하고 압수된 전자정보의 파일 명세가 특정된 압수목록을 작성ㆍ교부하여야 하며 범죄혐의사실과 무관한 전자정보의 임의적인 복제 등을 막기 위한 적절한 조치를 취하는 등 영장주의 원칙과 적법절차를 준수하여야 한다. 만약 그러한 조 치가 취해지지 않았다면 피압수자 측이 참여하지 아니한다는 의사 를 명시적으로 표시하였거나 절차 위반행위가 이루어진 과정의 성 질과 내용 등에 비추어 피압수자 측에 절차 참여를 보장한 취지가 실질적으로 침해되었다고 볼 수 없을 정도에 해당한다는 등의 특 별한 사정이 없는 이상 압수ㆍ수색이 적법하다고 평가할 수 없고, 비록 수사기관이 정보저장매체 또는 복제본에서 범죄혐의사실과 관련된 전자정보만을 복제ㆍ출력하였다 하더라도 달리 볼 것은 아 니다(대법원 2015. 7. 16. 자 2011모1839 전원합의체 결정, 대법원 2021. 11. 18. 선고 2016도348 전원합의체 판결 참조). 따라서 수사기관이 피압수자 측에게 참여의 기회를 보장하거나 압수한 전자정보 목록을 교부하지 않는 등 영장주의 원칙과 적법 절차를 준수하지 않은 위법한 압수ㆍ수색과정을 통하여 취득한 증 거는 위법수집증거에 해당하고, 사후에 법원으로부터 영장이 발부 되었다거나 피고인이나 변호인이 이를 증거로 함에 동의하였다고 하여 위법성이 치유되는 것도 아니다(위 대법원 2016도348 전원합 의체 판결 참조).",
