    "answer": "압수할 물건의 문언은 엄격히 해석해야 하므로 '보관 중인 물건'을 불리하게 '현존하는 물건'으로 확장할 수 없다.\n피압수자가 여러 명이면 원칙적으로 각자에게 영장을 제시해야 하며 장소 관리책임자에게 제시한 것으로 다른 소지자에 대한 제시를 갈음하지 못한다.\n압수목록은 사실에 부합하고 작성일을 기재해야 하며 권리행사에 지장이 없도록 원칙적으로 압수 직후 현장에서 작성·교부한다.",
