    "sourceQuote": "적법절차와 영장주의의 정신에 비추어 볼 때, 법관이 압수·수색영장을 발부하면서 ‘압수할 물건’을 특정하 기 위하여 기재한 문언은 엄격하게 해석하여야 하고, 함부로 피압수자 등에게 불리한 내용으로 확장 또는 유추 해석하여서는 안 된다. 따라서 압수·수색영장에 서 압수할 물건을 ‘압수장소에 보관중인 물건’이라고 기재하고 있는 것을 ‘압수장소에 현존하는 물건‘으로 해석할 수는 없다. 압수·수색영장은 처분을 받는 자에게 반드시 제시하 여야 하는바, 현장에서 압수·수색을 당하는 사람이 여러 명일 경우에는 그 사람들 모두에게 개별적으로 영장을 제시해야 하는 것이 원칙이다. 수사기관이 압 수·수색에 착수하면서 그 장소의 관리책임자에게 영 장을 제시하였다고 하더라도, 물건을 소지하고 있는 다른 사람으로부터 이를 압수하고자 하는 때에는 그 사람에게 따로 영장을 제시하여야 한다. 공무원인 수사기관이 작성하여 피압수자 등에게 교 부해야 하는 압수물 목록에는 작성연월일을 기재하 고, 그 내용은 사실에 부합하여야 한다. 압수물 목록 은 피압수자 등이 압수물에 대한 환부·가환부신청을 하거나 압수처분에 대한 준항고를 하는 등 권리행사 절차를 밟는 가장 기초적인 자료가 되므로, 이러한 권리행사에 지장이 없도록 압수 직후 현장에서 바로 작성하여 교부해야 하는 것이 원칙이다.",
