    "sourceQuote": "압수·수색영장을 집행하는 수사기관은 피압수자로 하 여금 법관이 발부한 영장에 의한 압수·수색이라는 사 실을 확인함과 동시에 형사소송법이 압수·수색영장에 필요적으로 기재하도록 정한 사항이나 그와 일체를 이루는 사항을 충분히 알 수 있도록 압수·수색영장을 제시하여야 한다. 나아가 압수·수색영장은 현장에서 피압수자가 여러 명일 경우에는 그들 모두에게 개별적으로 영장을 제 시해야 하는 것이 원칙이다. 수사기관이 압수·수색에 착수하면서 그 장소의 관리책임자에게 영장을 제시 하였더라도, 물건을 소지하고 있는 다른 사람으로부 터 이를 압수하고자 하는 때에는 그 사람에게 따로 영장을 제시하여야 한다.",
