    "caution": "현재 법상 별도 사본교부 의무와 영장 원본 제시 의무를 혼동하지 않는다. 사본을 보냈다는 것만으로 원본 제시가 대체되지 않는다.",
    "sourceQuote": "(1) 수사기관의 압수·수색은 법관이 발부한 압수수색영장에 의하 여야 하는 것이 원칙이고, 그 영장에는 피의자의 성명, 압수할 물 건, 수색할 장소·신체·물건과 압수수색의 사유 등이 특정되어야 하 며(형사소송법 제215조, 제219조, 제114조 제1항, 형사소송규칙 제 58조), 영장은 처분을 받는 자에게 반드시 제시되어야 하고(형사소 송법 제219조, 제118조), 압수물을 압수한 경우에는 목록을 작성하 여 소유자, 소지자 등에게 교부하여야 한다(같은 법 제219조, 제 129조). 이러한 형사소송법과 형사소송규칙의 절차 조항은 헌법에 서 선언하고 있는 적법절차와 영장주의를 구현하기 위한 것으로서 그 규범력은 확고히 유지되어야 한다. 그러므로 형사소송법 등에서 정한 절차에 따르지 않고 수집된 증거는 기본적 인권 보장을 위해 마련된 적법한 절차에 따르지 않은 것으로서 원칙적으로 유죄 인 정의 증거로 삼을 수 없다. (2) 원심은, 수사기관이 2010. 1. 11. 공소외 1 주식회사에서 압수 수색영장을 집행하여 피고인이 공소외 2에게 발송한 이메일(증거 목록 순번 314-1, 3, 5) 을 압수한 후 이를 증거로 제출하였으나, 수 사기관은 위 압수수색영장을 집행할 당시 공소외 1 주식회사에 팩 스로 영장 사본을 송신한 사실은 있으나 영장 원본을 제시하지 않 았고 또한 압수조서와 압수물 목록을 작성하여 이를 피압수·수색 당사자에게 교부하였다고 볼 수도 없다고 전제한 다음, 위와 같은 방법으로 압수된 위 각 이메일은 헌법과 형사소송법 제219조, 제 118조, 제129조가 정한 절차를 위반하여 수집한 위법수집증거로 원칙적으로 유죄의 증거로 삼을 수 없고, 이러한 절차 위반은 헌법 과 형사소송법이 보장하는 적법절차 원칙의 실질적인 내용을 침해 하는 경우에 해당하고 위법수집증거의 증거능력을 인정할 수 있는 예외적인 경우에 해당한다고 볼 수도 없어 증거능력이 없다는 이 유로, 이 부분 공소사실을 무죄로 판단한 제1심판결을 그대로 유 지하였다.",
