    "answer": "체포과정에 타고 있던 차량 수색·마약 압수는 체포현장 압수수색으로 적법하다.\n이미 체포가 완료되고 2km 떨어진 주거지는 체포장소로 볼 수 없다.\n주거지의 마약 소지가 명백하지 않고 도검의 단서도 없으며 사전영장을 받을 시간적 여유가 없었다고 단정할 수 없어 범행 중·직후의 범죄장소 긴급 압수 요건도 갖추지 못한다.",
