    "caution": "체포영장에 의한 체포를 긴급체포로 바꾸어 제217조를 적용하지 않는다. 제216조의 체포장소와 범죄장소 예외를 각각 심사한다.",
    "sourceQuote": "수사관들이 위 피고인이 체포과정에서 타고 있었던 차량을 수색하여 필로폰과 대마 등을 압수한 것은 형사소송법 제216조 제1항 제2호에 따른 것으로 적 법하다고 볼 수 있다. 그러나 수사관들이 별도의 압수 · 수색영장 없이 위 피고인의 주거지를 수색하여 도검을 압수한 것은 다 음과 같은 이유로 적법하다고 보기 어렵다. 수사관들이 위 피고인의 주거지에 대한 수색에 착수 할 당시에는 이미 위 피고인에 대한 체포가 완료된 상황이었을 뿐만 아니라, 위 피고인이 체포된 장소와 위 피고인의 주거지가 2킬로미터 정도 떨어져 있었 다는 사정을 감안하면 위 피고인의 주거지를 \"체포장 소\"라고 보기는 어렵다. 위 피고인에 대하여 필로폰 매도 등의 혐의로 체포 영장이 발부되었고 체포현장에서 마약류가 발견되었 던 사정을 고려할 때 수사관들은 위 피고인이 추가 로 소지하고 있을지 모를 마약류를 압수하기 위하여 위 피고인의 주거지를 수색한 것으로 보인다. 그러나 위와 같은 사정들만으로 수사관들이 위 압수 · 수색 에 착수할 당시 위 피고인이 주거지에 마약류를 소 지하고 있음이 명백하였다고 보기는 어려울 뿐만 아 니라 도검에 관하여는 수사관들이 그 소지에 관한 단서조차 가지고 있지 않았던 것으로 보이므로, 위 피고인의 주거지를 마약류 내지 도검의 소지에 관하 여 \"범행 중 또는 범행 직후\"라는 죄증이 명백하게 존재하는 범죄장소로 볼 수는 없다(대법원 2002. 5. 10. 선고 2001도300 판결, 대법원 2012. 2. 9. 선고 2009도14884 판결 참조). 또한 당시 위 피고인의 주 거지에 제3자가 동거 중이었으므로 위 피고인의 체 포사실이 알려지는 경우 위 주거지에 소지 중이던 마약류가 공범 등에 의하여 은닉될 위험성이 있었다 고는 보이나 위 피고인에 대하여 이미 사전에 필로 폰 매도 등 혐의로 체포영장이 발부되었던 사정을 고려하면 위 피고인의 주거지에 대한 압수 · 수색영 장을 미리 발부받을 시간적 여유가 없을 정도로 긴 급을 요하는 상황이었다고 섣불리 단정하기도 어렵 다.",
