    "sourceQuote": "범죄수사를 위하여 압수, 수색 또는 검증을 하려면 미리 영장을 발부받아야 한다는 이른바 사전영장주의가 원칙이지만, 형사소송법 제217조는 그 예외를 인정한다. 즉, 검사 또는 사법경찰관은 긴급 체포된 자가 소유·소지 또는 보관하는 물건에 대하여는 긴급히 압 수할 필요가 있는 경우에는 체포한 때부터 24시간 이내에 한하여 영장 없이 압수·수색 또는 검증을 할 수 있고(형사소송법 제217조 영장주의의 예외 - 8 6 - 6 주차 영 장 실 무 제1항), 압수한 물건을 계속 압수할 필요가 있는 경우에는 지체 없 이 압수수색영장을 청구하여야 한다. 이 경우 압수수색영장의 청구 는 체포한 때부터 48시간 이내에 하여야 한다(같은 조 제2항). 형사소송법 제217조 제1항은 수사기관이 피의자를 긴급체포한 상황에서 피의자가 체포되었다는 사실이 공범이나 관련자들에게 알려짐으로써 관련자들이 증거를 파괴하거나 은닉하는 것을 방지 하고, 범죄사실과 관련된 증거물을 신속히 확보할 수 있도록 하기 위한 것이다. 이 규정에 따른 압수·수색 또는 검증은 체포현장에서 의 압수·수색 또는 검증을 규정하고 있는 형사소송법 제216조 제1 항 제2호와 달리, 체포현장이 아닌 장소에서도 긴급체포된 자가 소유·소지 또는 보관하는 물건을 대상으로 할 수 있다.",
