    "answer": "체포영장 제시와 피의사실 요지·체포 이유·변호인 선임권 고지 및 변명기회는 원칙적으로 실력행사 전에 제공해야 한다.\n도주·폭력 대항을 제압할 때는 과정 중 또는 제압 뒤 지체 없이 할 수 있으나, 사전 고지 여유가 있는데 처음부터 사후 고지를 예정한 체포는 적법한 공무집행이 아니다.\n이 사건 저항행위는 공무집행방해가 성립하지 않고 불법체포를 벗어나려는 상해는 정당방위로 위법성이 조각된다.",
