    "caution": "경찰관이 영장을 소지했다는 사실만으로 집행이 항상 적법하지 않다. 피의자가 처음부터 도주·폭력으로 대항한 경우의 예외와 구별한다.",
    "sourceQuote": "[1] 사법경찰관 등이 체포영장을 소지하고 피의자를 체포하기 위 해서는 체포영장을 피의자에게 제시하고(형사소송법 제200조의6, 제85조 제1항), 피의사실의 요지, 체포의 이유와 변호인을 선임할 수 있음을 말하고 변명할 기회를 주어야 한다(형사소송법 제200조 의5). 이와 같은 체포영장의 제시나 고지 등은 체포를 위한 실력행 사에 들어가기 이전에 미리 하여야 하는 것이 원칙이다. 그러나 달 아나는 피의자를 쫓아가 붙들거나 폭력으로 대항하는 피의자를 실 력으로 제압하는 경우에는 붙들거나 제압하는 과정에서 하거나, 그 것이 여의치 않은 경우에는 일단 붙들거나 제압한 후에 지체 없이 하여야 한다. [2] 형법 제136조가 규정하는 공무집행방해죄는 공무원의 직무 집행이 적법한 경우에 한하여 성립한다. 이때 적법한 공무집행은 그 행위가 공무원의 추상적 권한에 속할 뿐 아니라 구체적 직무집 행에 관한 법률상 요건과 방식을 갖춘 경우를 가리킨다. 경찰관이 적법절차를 준수하지 않은 채 실력으로 피의자를 체포하려고 하였 다면 적법한 공무집행이라고 할 수 없다. 그리고 경찰관의 체포행위가 적법한 공무집행을 벗어나 불법하 게 체포한 것으로 볼 수밖에 없다면, 피의자가 그 체포를 면하려고 반항하는 과정에서 경찰관에게 상해를 가한 것은 불법체포로 인한 신체에 대한 현재의 부당한 침해에서 벗어나기 위한 행위로서 정 당방위에 해당하여 위법성이 조각된다.",
