    "sourceQuote": "구체적인 사안에서 2차적 증거들의 증거능력 인정 여부는 제반 사정을 전체적·종합적으로 고려하여 판 단하여야 한다. 예컨대 진술거부권을 고지하지 않은 것이 단지 수사기관의 실수일 뿐 피의자의 자백을 이끌어내기 위한 의도적이고 기술적인 증거확보의 방법으로 이용되지 않았고, 그 이후 이루어진 신문에 서는 진술거부권을 고지하여 잘못이 시정되는 등 수 사 절차가 적법하게 진행되었다는 사정, 최초 자백 이후 구금되었던 피고인이 석방되었다거나 변호인으 로부터 충분한 조력을 받은 가운데 상당한 시간이 경과하였음에도 다시 자발적으로 계속하여 동일한 내용의 자백을 하였다는 사정, 최초 자백 외에도 다 른 독립된 제3자의 행위나 자료 등도 물적 증거나 증인의 증언 등 2차적 증거 수집의 기초가 되었다는 사정, 증인이 그의 독립적인 판단에 의해 형사소송법 이 정한 절차에 따라 소환을 받고 임의로 출석하여 증언하였다는 사정 등은 통상 2차적 증거의 증거능 력을 인정할만한 정황에 속한다.",
