    "sourceQuote": " 압수의 대상이 되는 전자정보와 그렇지 않은 전자정보가 혼재된 정보저장매체나 그 복 제본을 임의제출받은 수사기관이 그 정보저 장매체 등을 수사기관 사무실 등으로 옮겨 이를 탐색 복제 출력하 는 경우, 그와 같은 일련의 과정에서 형사소송법 제219조, 제121조 에서 규정하는 피압수∙수색 당사자(이하 피압수자라 한다)나 그 변 호인에게 참여의 기회를 보장하고 압수된 전자정보의 파일 명세가 특정된 압수목록을 작성·교부하여야 하며 범죄혐의사실과 무관한 전자정보의 임의적인 복제 등을 막기 위한 적절한 조치를 취하는 등 영장주의 원칙과 적법절차를 준수하여야 한다. 만약 그러한 조 치가 취해지지 않았다면 피압수자 측이 참여하지 아니한다는 의사 를 명시적으로 표시하였거나 임의제출의 취지와 경과 또는 그 절 차 위반행위가 이루어진 과정의 성질과 내용 등에 비추어 피압수 자 측에 절차 참여를 보장한 취지가 실질적으로 침해되었다고 볼 수 없을 정도에 해당한다는 등의 특별한 사정이 없는 이상 압수·수 색이 적법하다고 평가할 수 없고, 비록 수사 기관이 정보저장매체 또는 복제본에서 범죄혐의사실과 관련된 전자정보만을 복제·출력하 였다 하더라도 달리 볼 것은 아니다.",
