    "answer": "위법수집증거와 이에 기초한 2차적 증거는 원칙적으로 배제한다. 절차위반이 적법절차의 실질을 침해하지 않고 증거배제가 형사사법정의의 취지에 반하는 예외를 인정할 특별한 사정은 검사가 증명한다.\n2차적 증거는 최초 위법부터 추가 수집까지 모든 사정을 종합하여 인과관계의 희석·단절을 판단한다.\n1차 증거가 수사개시의 단서·핵심증거이고 위법이 중하며 그 내용을 전제로 신문했다면, 법정진술이라는 사정만으로 단절되지 않는다. 다른 독립된 증거에 기인한 진술이라는 등의 특별한 사정도 검사가 증명해야 한다.",
