    "sourceQuote": " 형사소송법은 제161조의2에서 피고인의 반대신문권을 포함한 교 호신문제도를 규정하는 한편, 제310조의2에서 법관의 면전에서 진 술되지 아니하고 피고인에 의한 반대신문의 기회가 부여되지 아니 한 진술에 대하여는 원칙적으로 그 증거능력을 부여하지 아니함으 로써, 형사재판에서 증거는 법관의 면전에서 진술·심리되어야 한다 는 직접주의와 피고인에게 불리한 증거에 대하여 반대신문할 수 있는 권리를 원칙적으로 보장하고 있는데, 이러한 반대신문권의 보 장은 피고인에게 불리한 주된 증거의 증명력을 탄핵할 수 있는 기 회가 보장되어야 한다는 점에서 형식적·절차적인 것이 아니라 실 질적·효과적인 것이어야 한다.",
