    "answer": "피의자·피고인과 변호인의 의사교환에서 생성된 형사사건 법률자문·상담 자료의 압수는 변호인 조력권 침해로 원칙적으로 불허된다. 다만 피의자·피고인이 피압수자인 변호인에 대한 압수를 승낙하거나, 변호인의 공범·범죄 기타 위법행위 관여 등 중대한 공익상 필요가 있으면 예외적으로 허용한다. 중대성·증거가치와 중요성·조력권 침해 정도 등을 종합하여 엄격히 판단한다.\n영장상 압수물 범위를 벗어난 취득은 위법하며 사후영장·증거동의로 치유되지 않는다. 위법한 1차·2차 증거는 원칙적으로 배제되고, 적법절차의 실질 침해가 없고 배제가 형사사법정의에 반하는 예외에만 허용한다. 2차 증거는 모든 수집사정을 인과관계 희석·단절 중심으로 판단하고 특별사정은 검사가 증명한다.\n법정자백도 같다. 1차 증거가 수사단서·유일 또는 핵심증거이고 위법이 상당하며 수사 중 이를 제시받거나 그 내용으로 신문받았다면 단절 인정이 어렵다. 다른 독립증거에서 기인했다는 등의 특별사정이 증명되지 않은 이 사건은 녹음·녹취록뿐 아니라 법정진술·변호사 확인 수사보고도 배제되었다.",
