    "group": "공판중심주의",
    "prompt": "검사가 법정 증인을 미리 불러 면담한 뒤 증인이 불리하게 증언했다. 신빙성을 인정하기 위한 조건과 증명 주체는?",
    "answer": "검사가 증인신문 준비 등 필요에 따라 증인을 사전면담할 수는 있다. 다만 특별한 사정 없이 미리 소환·면담한 증인이 피고인에게 불리하게 증언하면 회유·압박·답변 유도·암시 등으로 법정진술에 영향을 미치지 않았다는 점이 담보되어야 신빙성을 인정할 수 있다. 회유·압박 등이 없었다는 사정은 검사가 법정진술 또는 면담기록 등으로 면담 시점·이유·방법·구체적 내용을 밝혀 증명해야 한다.",
