    "sourceQuote": "⚫ 형사소송법의 기본원칙에 비추어 보면, 검사가 공판기일에 증인 으로 신청하여 신문할 사람을 특별한 사정 없이 미리 수사기관 에 소환하여 면담하는 절차를 거친 후 증인이 법정에서 피고인 에게 불리한 내용의 진술을 한 경우, 검사가 증인신문 전 면담 과정에서 증인에 대한 회유나 압박, 답변 유도나 암시 등으로 증 인의 법정진술에 영향을 미치지 않았다는 점이 담보되어야 증인 의 법정진술을 신빙할 수 있다고 할 것이다. ⚫ 검사가 증인신문 준비 등 필요에 따라 증인을 사전 면담할 수 있다고 하더라도 법원이나 피고인의 관여 없이 일방적으로 사전 면담하는 과정에서 증인이 훈련되거나 유도되어 법정에서 왜곡 된 진술을 할 가능성도 배제할 수 없기 때문이다. 증인에 대한 회유나 압박 등이 없었다는 사정은 검사가 증인의 법정진술이나 면담 과정을 기록한 자료 등으로 사전면담 시점, 이유와 방법, 구체적 내용 등을 밝힘으로써 증명하여야 한다.",
