    "answer": "저장매체·복제본을 사무실로 옮겨 복제·탐색·출력할 때에도 피압수자 또는 변호인에게 참여기회를 보장하고 무관한 정보의 임의 복제를 막는 적절한 조치를 해야 한다. 혼재된 저장매체를 임의제출받은 경우에도 같다.\n명시적 불참 의사나 참여권 취지가 실질적으로 침해되지 않은 특별한 사정이 없다면 위반한 압수수색은 위법하다. 관련 정보만 골라 출력했더라도 같다.\n변호인의 참여권은 고유권이므로 피압수자가 불참 의사를 밝혀도 특별한 사정이 없는 한 변호인에게 별도 참여기회를 보장해야 한다.",
