    "answer": "구 성폭력처벌법 제30조 제6항 중 신뢰관계인·진술조력인의 진정성립 진술만으로 증거능력을 부여하던 19세 미만 피해자 부분은 2018헌바524 위헌결정 대상이다. 결정 당시 계속 중인 이 사건에도 효력이 미쳐 영상물의 증거능력 근거가 될 수 없고 속기록의 근거도 없다.\n같은 내용의 구 아청법 제26조 제6항은 당시 직접 위헌심판 대상이 아니어서 적용 여지는 있었으나 동일한 위헌 문제가 있었다. 법원은 그 조항의 위헌 여부 또는 위헌적 결과를 피하기 위한 피해자 소환·신문 및 피고인 반대신문 기회 부여 필요 등을 심리·판단해야 한다. 이를 생략하고 유죄 증거로 사용한 원심은 파기환송되었다.\n이는 구법 사건이지 현행법상 반대신문 기회만 있으면 언제나 허용된다는 판결이 아니다. 현행 제30조의2는 적법한 녹화절차와 별도 요건을 정하고, 진술불능·특신상태에 의한 예외 경로도 둔다.",
