    "reviewNote": "구법 판례와 2023.10.12. 시행된 현행 제30조의2를 구별한다. 현행법은 제30조 제4~6항의 절차·방식 준수를 전제로 ① 증거보전·공판준비·공판기일의 피의자·피고인·변호인 신문기회(증거보전은 방어권 보장 아래 충분한 반대신문을 법원이 인정할 것), 또는 ② 사망·외국거주·신체적/정신적 질병·장애·소재불명 등 진술불능과 진술·녹화의 특신성 증명을 요구한다. ②를 유죄 증거로 채택할 때에는 관계·범행내용·피해자 나이·심신·심리적 외상·녹화진술 내용과 태도 등을 고려하고 전문심리위원 또는 전문가 의견을 들어야 한다. 2026.10.2. 시행 법률에서도 제30조의2를 확인했다."
